(*注释掉的ListenBoardInputConfig是对应的限位信号是否配置,暂时屏蔽*)

(*U2轴报警*)
IF g_bU2AxisEnable THEN
  IF Axis_U.NCTOPLC.POSSOFTWARN AND g_bU2HomeDone THEN
    g_Alarm.alarmArray[0] := 700;
  ELSE
    g_Alarm.alarmArray[0] := 0;
  END_IF;
  IF Axis_U.NCTOPLC.NEGSOFTWARN AND g_bU2HomeDone THEN
    g_Alarm.alarmArray[1] := 701;
  ELSE
    g_Alarm.alarmArray[1] := 0;
  END_IF;
  IF NOT Axis_U.NCTOPLC.HOMINGSTATE THEN
    g_Alarm.alarmArray[2] := 702;
  ELSE
    g_Alarm.alarmArray[2] := 0;
  END_IF;
  (*绝对式回原限位也要报警*)
  IF g_nUHomeMode = 1 THEN
    IF g_bUAxisPosLimit (*AND ListenBoardInputConfig[24]*)  THEN
		g_Alarm.alarmArray[3] := 703;
	ELSE
		g_Alarm.alarmArray[3] := 0;
	END_IF;
    IF g_bUAxisNegLimit  (*AND ListenBoardInputConfig[26] *)  THEN
		g_Alarm.alarmArray[4] := 704;
    ELSE
		g_Alarm.alarmArray[4] := 0;
    END_IF;
  ELSE
     IF g_bUAxisPosLimit AND Axis_U.NCTOPLC.AXISSTATE<>5 (*AND ListenBoardInputConfig[24]*) THEN
		g_Alarm.alarmArray[3] := 703;
	ELSE
		g_Alarm.alarmArray[3] := 0;
	END_IF;
    IF g_bUAxisNegLimit AND Axis_U.NCTOPLC.AXISSTATE<>5 (*AND ListenBoardInputConfig[26]*) THEN
		g_Alarm.alarmArray[4] := 704;
	  ELSE
		g_Alarm.alarmArray[4] := 0;
	  END_IF;
  END_IF;

END_IF;

